package cn.xingbao.domain;
import jakarta.persistence.Entity;
@Entity public class CommunityComment extends BaseEntity { private Long postId; private Long userId; private String body; private boolean anonymous; private String status="PENDING"; private String riskLevel; public Long getPostId(){return postId;} public void setPostId(Long v){postId=v;} public Long getUserId(){return userId;} public void setUserId(Long v){userId=v;} public String getBody(){return body;} public void setBody(String v){body=v;} public boolean isAnonymous(){return anonymous;} public void setAnonymous(boolean v){anonymous=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getRiskLevel(){return riskLevel;} public void setRiskLevel(String v){riskLevel=v;} }
